// Infinitary queue 12. Generated by Infinitary from one source; a newer Infinitary offers its update as a pull request, so change it there, not by hand.
import { labelApproval, newestTrustedApproval, readCommitApproval } from "./message.mjs";
/**
 * The shipped queue's GitHub part (docs/forge.md, "The shipped queue"): it
 * runs the host-neutral rules in rules.mjs inside GitHub Actions, through
 * actions/github-script's client. It reads open pull requests, the
 * infinitary/queue commit status on each version, the queue's own runs and
 * their jobs' logs, and writes statuses, the pause's issue and the queue's
 * next start. It runs with the workflow's own credential, so its writes
 * start no other workflow except dispatches. A separate merge job merges
 * passed versions and signals the project once after its merges.
 */
import {
  answerWords,
  CONFIRM_JOB,
  confirmPlan,
  conflictsWithMain,
  FIX_LABEL,
  failedTestFiles,
  formBatch,
  headList,
  inBatch,
  labelQueues,
  PAUSE_LABEL,
  pauseIssue,
  pauseWrites,
  QUEUE,
  QUEUE_LABEL,
  REMOVED,
  readComposition,
  readPauseMarker,
  readQueueState,
  resume,
  sendBack,
  verdict,
  WAITING,
} from "./rules.mjs";

/** The queue's workflow file, which its next start names. */
export const WORKFLOW = "infinitary-queue.yml";

/** Who GitHub names as the writer of anything this workflow's own key writes. */
const QUEUE_WRITER = "github-actions[bot]";

const defaultBranch = (context) => context.payload.repository?.default_branch ?? "main";
const runUrl = (context) =>
  `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

/** The queue statuses on one version, newest first, in the rules' shape. */
async function queueStatuses(github, repo, ref) {
  const statuses = await github.paginate(github.rest.repos.listCommitStatusesForRef, {
    ...repo,
    ref,
    per_page: 100,
  });
  return statuses
    .filter((status) => status.context === QUEUE)
    .map((status) => ({
      state: status.state,
      description: status.description ?? "",
      url: status.target_url ?? "",
      createdAt: status.created_at,
      writer: status.creator?.login,
    }));
}

async function queueAt(github, repo, ref) {
  const statuses = await queueStatuses(github, repo, ref);
  const state = readQueueState(statuses);
  // Status-write access must never become the queue job's code-write authority.
  if (state?.kind === "passed" && statuses[0]?.writer !== QUEUE_WRITER) {
    const rejected = {
      head: ref,
      state: "failure",
      description: "Rejected queue pass: the queue did not write it",
      url: statuses[0]?.url ?? "",
    };
    await writeStatus(github, repo, rejected);
    return readQueueState([{ ...rejected, createdAt: statuses[0]?.createdAt }]);
  }
  return state;
}

/** Every open pull request with its version, the branch it targets, whether it carries the fix label, and its queue state. */
export async function readOpenQueue(github, repo) {
  const pulls = await github.paginate(github.rest.pulls.list, {
    ...repo,
    state: "open",
    per_page: 100,
  });
  return Promise.all(
    pulls.map(async (pull) => ({
      number: pull.number,
      head: pull.head.sha,
      base: pull.base.ref,
      fix: (pull.labels ?? []).some((label) => label.name === FIX_LABEL),
      queue: await queueAt(github, repo, pull.head.sha),
    })),
  );
}

/**
 * When each change carrying the fix label was last labelled so, from its
 * events, read only while a change is paused, since only a pause asks
 * whether a fix came after it began. A labelled change no event dates
 * keeps no time, and ends no pause.
 */
async function readFixTimes(github, repo, entries) {
  if (!entries.some((entry) => entry.queue?.kind === "paused")) return entries;
  return Promise.all(
    entries.map(async (entry) => {
      if (!entry.fix) return entry;
      const events = await github.paginate(github.rest.issues.listEvents, {
        ...repo,
        issue_number: entry.number,
        per_page: 100,
      });
      const times = events
        .filter((event) => event.event === "labeled" && event.label?.name === FIX_LABEL)
        .map((event) => event.created_at)
        .filter((at) => Number.isFinite(Date.parse(at ?? "")))
        .sort((a, b) => Date.parse(a) - Date.parse(b));
      return times.length ? { ...entry, fixLabelledAt: times.at(-1) } : entry;
    }),
  );
}

/** The queue runs that changes in a batch name, one reading each. */
async function readRuns(github, repo, entries) {
  const ids = [
    ...new Set(
      entries.flatMap((entry) => (entry.queue?.kind === "in-batch" ? [entry.queue.run] : [])),
    ),
  ];
  const runs = new Map();
  for (const id of ids)
    runs.set(id, (await github.rest.actions.getWorkflowRun({ ...repo, run_id: id })).data);
  return runs;
}

/**
 * Each change of a batch run as its verdict reads it: the pull request's
 * current version and the queue state there while it is open, and `swept`,
 * the swept version's state, when it was pushed again since.
 */
async function readCurrent(github, repo, members) {
  const current = new Map();
  for (const member of members) {
    const { data: pull } = await github.rest.pulls.get({ ...repo, pull_number: member.number });
    const head = pull.head.sha;
    if (pull.state !== "open") current.set(member.number, { head, queue: null });
    else if (head === member.head)
      current.set(member.number, { head, queue: await queueAt(github, repo, head) });
    else
      current.set(member.number, {
        head,
        queue: await queueAt(github, repo, head),
        swept: await queueAt(github, repo, member.head),
      });
  }
  return current;
}

function writeStatus(github, repo, write) {
  return github.rest.repos.createCommitStatus({
    ...repo,
    sha: write.head,
    state: write.state,
    context: QUEUE,
    description: write.description,
    target_url: write.url,
  });
}

/**
 * Close the pause's open issue, if there is one, saying what ended it. A
 * project that cannot list its issues (Issues turned off) has none to
 * close: its pause is held by the statuses alone, so the answer goes on.
 */
async function closePause(github, repo, words) {
  let issues;
  try {
    issues = await github.paginate(github.rest.issues.listForRepo, {
      ...repo,
      state: "open",
      labels: PAUSE_LABEL,
      per_page: 100,
    });
  } catch {
    return;
  }
  for (const issue of issues) {
    await github.rest.issues.createComment({ ...repo, issue_number: issue.number, body: words });
    await github.rest.issues.update({ ...repo, issue_number: issue.number, state: "closed" });
  }
}

/** Start the queue again, so the next batch forms from what the queue reads then. */
function startForm(github, context) {
  return github.rest.actions.createWorkflowDispatch({
    ...context.repo,
    workflow_id: WORKFLOW,
    ref: defaultBranch(context),
    inputs: { action: "form" },
  });
}

const FAILED = ["failure", "timed_out", "cancelled"];
const inConfirm = (name) => name === CONFIRM_JOB || name.startsWith(`${CONFIRM_JOB} / `);

/** The run's observed jobs, kept even when none supplies a failed test. */
async function readJobResults(github, repo, run) {
  return github.paginate(github.rest.actions.listJobsForWorkflowRun, {
    ...repo,
    run_id: run,
    per_page: 100,
  });
}

/** Failed jobs outside the confirm, with test files their available logs name. */
async function readFailedJobs(github, repo, jobs) {
  const failed = [];
  for (const job of jobs) {
    if (!FAILED.includes(job.conclusion) || inConfirm(job.name)) continue;
    let files = [];
    try {
      const { data: log } = await github.rest.actions.downloadJobLogsForWorkflowRun({
        ...repo,
        job_id: job.id,
      });
      files = failedTestFiles(typeof log === "string" ? log : Buffer.from(log).toString("utf8"));
    } catch {
      // A log GitHub cannot give names no file.
    }
    failed.push({ name: job.name, url: job.html_url ?? "", files });
  }
  return failed;
}

/** Each failed test file, with the batch's changes whose diffs touch it. */
async function touchingChanges(github, repo, failedJobs, members) {
  const files = [...new Set(failedJobs.flatMap((job) => job.files))];
  if (!files.length) return [];
  const changed = new Map();
  for (const member of members) {
    const diff = await github.paginate(github.rest.pulls.listFiles, {
      ...repo,
      pull_number: member.number,
      per_page: 100,
    });
    changed.set(
      member.number,
      new Set(diff.flatMap((entry) => [entry.filename, entry.previous_filename].filter(Boolean))),
    );
  }
  return files.map((file) => ({
    file,
    touchedBy: members
      .filter((member) => changed.get(member.number).has(file))
      .map((member) => member.number),
  }));
}

/**
 * The form job: read every open change and decide the next batch. When a
 * fix labelled after the pause began is approved, it ends the pause: the
 * paused changes wait again and the pause's issue closes before the batch
 * composes. Its outputs are the members and their `<number>:<version>` list
 * for the compose step.
 */
export async function form({ github, context, core }) {
  const repo = context.repo;
  const entries = await readFixTimes(github, repo, await readOpenQueue(github, repo));
  const plan = formBatch(entries, await readRuns(github, repo, entries), defaultBranch(context));
  core.notice(plan.reason);
  if (plan.resumes.length) {
    for (const member of plan.resumes)
      await writeStatus(github, repo, {
        ...member,
        state: "pending",
        description: WAITING,
        url: runUrl(context),
      });
    await closePause(
      github,
      repo,
      `${plan.fixes.map((number) => `#${number}`).join(", ")} was approved as the fix, so the pause ended and [batch run ${context.runId}](${runUrl(context)}) takes every paused and waiting change.`,
    );
  }
  core.setOutput("members", JSON.stringify(plan.members));
  core.setOutput("heads", headList(plan.members));
}

/**
 * After the compose step: a change that conflicts with the default branch
 * alone goes back to be brought up to date, one that conflicts only with
 * an earlier change here waits for the next batch, and the rest are in this
 * run. Its outputs name what the checks compose, the default branch's
 * version they compose onto (fetched after `form` read the queue, never
 * the job's own checkout) and the batch's tree.
 */
export async function mark({ github, context, core, output, members }) {
  const repo = context.repo;
  const composed = readComposition(output, members);
  core.notice(`The batch composes onto ${defaultBranch(context)} at ${composed.base}.`);
  for (const member of composed.conflictsMain)
    await writeStatus(github, repo, conflictsWithMain(member, runUrl(context)));
  for (const member of composed.merged)
    await writeStatus(github, repo, {
      ...member,
      state: "pending",
      description: inBatch(context.runId),
      url: runUrl(context),
    });
  for (const member of composed.conflictsBatch)
    core.notice(
      `#${member.number} conflicts only with an earlier change here, so it waits for the next batch.`,
    );
  core.setOutput("run", composed.merged.length ? "true" : "false");
  core.setOutput("members", JSON.stringify(composed.merged));
  core.setOutput("heads", headList(composed.merged));
  core.setOutput("base", composed.base);
  core.setOutput("tree", composed.tree);
}

/**
 * After red batch checks: what the confirm runs again on the same batch,
 * as the outputs `jobs` (the failed jobs' names, one a line) and `files`
 * (the failed test files, separated by spaces). Both are empty when a
 * failed job's log named no test file, and then nothing runs again.
 */
export async function failures({ github, context, core }) {
  const jobs = await readJobResults(github, context.repo, context.runId);
  const plan = confirmPlan(await readFailedJobs(github, context.repo, jobs));
  core.notice(
    plan
      ? `The batch checks run once more on the same batch for ${plan.jobs.split("\n").join(", ")} (${plan.files}).`
      : "A failed job's log named no failed test file, so nothing runs again and the batch pauses.",
  );
  core.setOutput("jobs", plan?.jobs ?? "");
  core.setOutput("files", plan?.files ?? "");
}

/**
 * The verdict job: green passes every change still in this run, and so
 * does a red batch whose confirm passed (`confirm`, that job's result);
 * otherwise it pauses them behind one new issue that names the failed
 * checks, the failed test files and the paused changes, and blames no
 * change.
 */
export async function decide({ github, context, core, result, members, tree, confirm = "" }) {
  const repo = context.repo;
  const run = context.runId;
  const current = await readCurrent(github, repo, members);
  let failed = [];
  let failedFiles = [];
  let jobs = [];
  if (result !== "success") {
    jobs = await readJobResults(github, repo, run);
    const failedJobs = await readFailedJobs(github, repo, jobs);
    failed = failedJobs.map((job) => ({ name: job.name, url: job.url }));
    failedFiles = await touchingChanges(github, repo, failedJobs, members);
  }
  const decided = verdict({
    run,
    runUrl: runUrl(context),
    result,
    tree,
    members,
    current,
    failed,
    failedFiles,
    confirm,
    jobs: jobs.map((job) => ({
      name: job.name,
      status: job.status,
      conclusion: job.conclusion,
      url: job.html_url ?? "",
    })),
  });
  for (const write of decided.writes) await writeStatus(github, repo, write);
  if (decided.pause) {
    // The paused statuses are the pause itself: they go first, linked to
    // the run, so a failed issue (Issues turned off) still holds the batch.
    for (const write of pauseWrites(decided.pause, runUrl(context)))
      await writeStatus(github, repo, write);
    // A workflow rerun keeps its run id. Reuse its pause rather than open
    // another report or overwrite the repairer's diagnosis and claim.
    const issues = await github.paginate(github.rest.issues.listForRepo, {
      ...repo,
      state: "open",
      labels: PAUSE_LABEL,
      per_page: 100,
    });
    const existing = issues.find((issue) => readPauseMarker(issue.body)?.run === run);
    const opened =
      existing ??
      (
        await github.rest.issues.create({
          ...repo,
          ...pauseIssue(decided.pause, runUrl(context)),
          labels: [PAUSE_LABEL],
        })
      ).data;
    for (const write of pauseWrites(decided.pause, opened.html_url))
      await writeStatus(github, repo, write);
  }
  if (decided.next === "form") await startForm(github, context);
  await core.summary.addHeading("Batch verdict").addRaw(decided.summary).write();
}

/**
 * A by-hand answer to a pause, from any teammate's Infinitary or the
 * workflow's own page: `resume` turns every paused change back to waiting,
 * and `send-back` fails the named change with the reason first, on the
 * version the queue holds it at; a pull request that moved on from that
 * version gets nothing written, and the issue says so. Both need a reason,
 * close the pause's issue with it and start the next batch.
 */
export async function answer({ github, context, core, action, number, reason }) {
  if (!reason?.trim()) throw new Error("Say why the queue may go on.");
  const repo = context.repo;
  const url = runUrl(context);
  const entries = await readOpenQueue(github, repo);
  let except;
  let sent = false;
  let held = null;
  if (action === "send-back") {
    const wanted = Number(number);
    let entry = entries.find((candidate) => candidate.number === wanted);
    if (!entry) {
      const { data: pull } = await github.rest.pulls.get({ ...repo, pull_number: wanted });
      entry = {
        number: pull.number,
        head: pull.head.sha,
        queue: await queueAt(github, repo, pull.head.sha),
      };
    }
    const write = sendBack(entry, { reason, url });
    if (write) await writeStatus(github, repo, write);
    sent = Boolean(write);
    held = entry.queue;
    except = entry.number;
  } else if (action !== "resume") throw new Error(`Unknown answer: ${action}.`);
  let endedRun;
  if (sent && held?.kind === "in-batch") {
    const run = held.run;
    const { data: batch } = await github.rest.actions.getWorkflowRun({ ...repo, run_id: run });
    if (batch.status !== "completed") {
      const jobs = await github.paginate(github.rest.actions.listJobsForWorkflowRun, {
        ...repo,
        run_id: run,
        per_page: 100,
      });
      if (jobs.some((job) => FAILED.includes(job.conclusion))) {
        // Cancel before releasing its members: a refused cancellation must
        // not allow a second batch to run beside this one.
        await github.rest.actions.cancelWorkflowRun({ ...repo, run_id: run });
        endedRun = run;
        core.notice(
          `Batch run ${run} already has a failed check and a change was sent back, so it ends now.`,
        );
      }
    }
  }
  // Read again after cancellation, so pushed or independently answered
  // versions are not overwritten with the snapshot from before send-back.
  const writes = resume(await readOpenQueue(github, repo), { url, except, endedRun });
  for (const write of writes) await writeStatus(github, repo, write);
  const words = answerWords({
    number: except,
    sent,
    queue: held,
    reason,
    resumed: writes.length,
    endedRun,
  });
  await closePause(github, repo, words.issue);
  await startForm(github, context);
  core.notice(words.log);
}

/**
 * The label job, on a pull request labelled infinitary-queue: it runs this
 * file from the default branch with write access, even for a fork's pull
 * request, so it reads the pull request only through GitHub's API and
 * never checks out or runs its code. The label comes off once read. Only a
 * labeller with write access queues, and only the version the label went
 * on: the queue writes that version's approval record, with the title and
 * description as its merge words, then marks it waiting and starts the
 * queue, since a status its own key writes starts no workflow.
 */
export async function labelled({ github, context, core }) {
  const repo = context.repo;
  const { pull_request: labelledPull, label, sender } = context.payload;
  if (label?.name !== QUEUE_LABEL || !labelledPull) return;
  const number = labelledPull.number;
  try {
    await github.rest.issues.removeLabel({ ...repo, issue_number: number, name: QUEUE_LABEL });
  } catch (error) {
    // Someone took it off already; the label was still put on.
    if (error?.status !== 404) throw error;
  }
  const { data: pull } = await github.rest.pulls.get({ ...repo, pull_number: number });
  if (pull.state !== "open")
    return core.notice(`#${number} is not open, so the label queues nothing.`);
  const entry = {
    number,
    head: pull.head.sha,
    base: pull.base.ref,
    queue: await queueAt(github, repo, pull.head.sha),
  };
  const decided = labelQueues({
    entry,
    main: defaultBranch(context),
    trusted: await mayMerge(github, repo, sender?.login, new Map()),
    moved: pull.head.sha !== labelledPull.head?.sha,
  });
  core.notice(decided.reason);
  if (!decided.queue) return;
  await github.rest.issues.createComment({
    ...repo,
    issue_number: number,
    body: labelApproval(entry.head, pull.body ?? "", pull.title),
  });
  await writeStatus(github, repo, {
    head: entry.head,
    state: "pending",
    description: WAITING,
    url: runUrl(context),
  });
  await startForm(github, context);
}

/** Only the merge job calls this: no code from a batch runs with its write key. */
export async function mergePassed({ github, context, core }) {
  const repo = context.repo;
  const entries = (await readOpenQueue(github, repo))
    .filter((entry) => entry.base === defaultBranch(context) && entry.queue?.kind === "passed")
    .sort((a, b) => Date.parse(a.queue.since) - Date.parse(b.queue.since) || a.number - b.number);
  let merged = 0;
  let base;
  try {
    let statusFailure;
    for (const entry of entries) {
      const withdrawn = async (record) => {
        if (record?.kind !== "revocation") return false;
        await writeStatus(github, repo, {
          head: entry.head,
          state: "failure",
          description: REMOVED,
          url: runUrl(context),
        });
        return true;
      };
      try {
        const { data: pull } = await github.rest.pulls.get({ ...repo, pull_number: entry.number });
        if (
          pull.state !== "open" ||
          pull.head.sha !== entry.head ||
          pull.base.ref !== defaultBranch(context)
        )
          continue;
        const queue = await queueAt(github, repo, entry.head);
        if (queue?.kind !== "passed" || queue.run !== entry.queue.run) continue;
        const approval = await readApproval(github, repo, entry.number, entry.head);
        if (await withdrawn(approval)) continue;
        if (approval?.kind !== "approval")
          throw new Error(
            "No current trusted approval for this version; it was withdrawn or has not been approved.",
          );
        const words = readCommitApproval(approval.body, entry.head, pull.title);
        const still = await queueAt(github, repo, entry.head);
        if (still?.kind !== "passed" || still.run !== queue.run) continue;
        if (!base)
          base = (await github.rest.repos.getBranch({ ...repo, branch: defaultBranch(context) }))
            .data.commit.sha;
        const finalApproval = await readApproval(github, repo, entry.number, entry.head);
        if (await withdrawn(finalApproval)) continue;
        if (
          finalApproval?.kind !== "approval" ||
          finalApproval.id !== approval.id ||
          finalApproval.body !== approval.body
        )
          throw new Error("The merge approval changed or was withdrawn before the merge.");
        let receipt;
        try {
          receipt = (
            await github.rest.pulls.merge({
              ...repo,
              pull_number: entry.number,
              sha: entry.head,
              merge_method: "squash",
              commit_title: words.title,
              commit_message: words.body,
              request: { retries: 0 },
            })
          ).data;
        } catch (error) {
          // A missing response is not permission to replay a merge. Read its receipt instead.
          const after = await github.rest.pulls
            .get({ ...repo, pull_number: entry.number })
            .catch(() => null);
          if (!after?.data.merged || after.data.head.sha !== entry.head) throw error;
          receipt = { merged: true };
        }
        if (!receipt.merged)
          throw new Error(
            `GitHub did not merge #${entry.number}: ${receipt.message ?? "no receipt"}`,
          );
        merged++;
        core.notice(`Merged #${entry.number} at its passed version.`);
      } catch (error) {
        const reason = `Queue merge failed: ${error instanceof Error ? error.message : String(error)}`;
        core.notice(`#${entry.number}: ${reason}`);
        try {
          // GitHub's status description has a physical 140-character maximum.
          await writeStatus(github, repo, {
            head: entry.head,
            state: "failure",
            description: reason.slice(0, 140),
            url: runUrl(context),
          });
        } catch (writeError) {
          statusFailure = writeError;
          core.notice(
            `#${entry.number}: could not publish the merge failure: ${String(writeError)}`,
          );
        }
      }
    }
    if (statusFailure) throw statusFailure;
  } finally {
    // Even a later refusal must not hide merges already made. Never retry an unknown merge.
    try {
      if (merged)
        await github.rest.repos.createDispatchEvent({
          ...repo,
          event_type: "infinitary-after-merge",
          client_payload: { base },
        });
    } finally {
      if (entries.length) await startForm(github, context);
    }
  }
}

/** The roles GitHub identifies as able to merge into the project's default branch. */
export const MERGE_PERMISSIONS = Object.freeze(["write", "maintain", "admin"]);

async function readApproval(github, repo, number, head) {
  const comments = await github.paginate(github.rest.issues.listComments, {
    ...repo,
    issue_number: number,
    per_page: 100,
  });
  const roles = new Map();
  return newestTrustedApproval(comments, head, (comment) => {
    const login = comment.user?.login;
    // The queue's own label records: only a job of the project's own workflows writes as it.
    if (login === QUEUE_WRITER) return true;
    return mayMerge(github, repo, login, roles);
  });
}

/** Whether GitHub says this person may merge into the project, read once per person. */
async function mayMerge(github, repo, login, roles) {
  if (!login) return false;
  if (!roles.has(login))
    roles.set(
      login,
      (
        await github.rest.repos
          .getCollaboratorPermissionLevel({ ...repo, username: login })
          .catch((error) => {
            if (error?.status === 404) return { data: { permission: "none" } };
            throw error;
          })
      ).data.permission,
    );
  return MERGE_PERMISSIONS.includes(roles.get(login));
}
